<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/config.php';
if (empty($_SESSION['user'])) { header('Location: login.php'); exit; }
$u=$_SESSION['user'];$settings=[];try{$q=db()->query('SELECT setting_key,setting_value FROM madapt_settings');foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r)$settings[$r['setting_key']]=$r['setting_value'];}catch(Throwable $e){}
$company=$settings['company_name']??'MADAPT ULDs';$logo=$settings['logo_path']??'';$aircraft=$settings['aircraft_path']??'';$role=strtoupper((string)($u['role']??'OPERATOR'));$isAdmin=$role==='ADMIN';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($company)?> — MADAPT ULDs</title><link rel="stylesheet" href="assets/app.css"><style>:root{--primary:<?=htmlspecialchars($settings['primary']??'#087a46')?>;--accent:<?=htmlspecialchars($settings['accent']??'#1b8b5b')?>;--sidebar:<?=htmlspecialchars($settings['sidebar']??'#006b3c')?>}.profile-btn{border:0;background:#fff;display:flex;align-items:center;gap:10px;border-radius:28px;padding:6px 14px;cursor:pointer}.profile-btn img{width:34px;height:34px;border-radius:50%;object-fit:cover}.upload-row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.upload-row input[type=file]{flex:1;min-width:240px}.media-preview{display:flex;gap:18px;align-items:center;margin-top:12px}.media-preview img{max-height:80px;max-width:180px;object-fit:contain;border-radius:8px}.profile-box{max-width:620px}.profile-photo{width:110px;height:110px;border-radius:50%;object-fit:cover;border:4px solid #e8f1ed}.profile-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}</style></head><body><div id="app"><aside id="sidebar"><div class="brand"><?php if($logo):?><img src="<?=htmlspecialchars($logo)?>" alt="Logo"><?php else:?><div class="brand-text">Ethiopian<br><small>AIRLINES</small></div><?php endif;?><strong>MADAPT ULDs</strong></div><nav><button data-page="dash">⌂ <span>Dashboard</span></button><button data-page="move">↔ <span>In / Out</span></button><button data-page="inv">▣ <span>Inventory</span></button><button data-page="hist">◷ <span>History</span></button><button data-page="report">▥ <span>Reports</span></button><button data-page="portals">🌐 <span>Portals</span></button><?php if($isAdmin):?><button data-page="users">♙ <span>Users</span></button><button data-page="set">⚙ <span>Settings</span></button><?php endif;?><button data-page="profile">◉ <span>My Profile</span></button><button id="logoutBtn">⇥ <span>Logout</span></button></nav></aside><main><header><div><h1>MADAPT ULDs</h1><p>Inventory Management System</p></div><button class="profile-btn" onclick="show('profile')"><?php if(!empty($u['profile_photo'])):?><img src="<?=htmlspecialchars($u['profile_photo'])?>" alt="Profile"><?php endif;?><?=htmlspecialchars($u['full_name']??$u['username']??'')?></button></header><section id="content"><div class="box"><b>Loading...</b></div></section></main></div><script>
const IS_ADMIN=<?=$isAdmin?'true':'false'?>,USER_ROLE=<?=json_encode($role)?>,COMPANY=<?=json_encode($company)?>,LOGO=<?=json_encode($logo)?>,AIRCRAFT=<?=json_encode($aircraft)?>,CURRENT_USER=<?=json_encode($u,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?>;const ULD_TYPES=['AKE','PAJ','PMC','PAG'];let stock=[],hist=[],flights=[],recipients=[],portalList=[];
async function A(action,data={},form=false){const opts={method:'POST'};if(form)opts.body=data;else{opts.headers={'Content-Type':'application/json'};opts.body=JSON.stringify(data)}const r=await fetch('api.php?action='+encodeURIComponent(action),opts);let j;try{j=await r.json()}catch(e){throw new Error('Invalid server response (HTTP '+r.status+')')}if(!j.ok)throw new Error(j.error||'Request failed');return j}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]) )}function stockState(x){const cur=Number(x.current_stock??0),min=Number(x.minimum_level??10);if(cur<=min)return'low';if(cur<=min+Math.max(3,Math.ceil(min*.25)))return'warning';return'ok'}function stateLabel(s){return s==='low'?'LOW STOCK':s==='warning'?'NEAR MINIMUM':'OK'}function movementType(x){return x.movement_type??x.type??''}function uldType(x){return x.uld_type??x.uld??''}function qty(x){return Number(x.quantity??x.qty??0)}function flight(x){return x.flight_number??x.flight??''}function userName(x){return x.user_name??x.username??''}
async function load(){const[s,h]=await Promise.all([A('stock'),A('history')]);stock=s.stock||[];hist=h.history||h.movements||[];flights=s.flights||[]}
function lowAlert(){const low=stock.filter(x=>stockState(x)==='low');if(!low.length)return'<div class="stock-alert good-alert">✓ All ULD stock levels are above the minimum.</div>';return'<div class="stock-alert danger-alert"><span class="blink-dot"></span><b>LOW STOCK ALERT</b><span>'+low.map(x=>esc(uldType(x))+' — '+Number(x.current_stock)+' / '+Number(x.minimum_level)).join(' &nbsp; • &nbsp; ')+'</span></div>'}
function stockCards(){return'<div class="uld-grid">'+stock.map(x=>{const s=stockState(x),cur=Number(x.current_stock),min=Number(x.minimum_level);return`<div class="uld-card ${s}"><div class="uld-head"><span>${esc(uldType(x))}</span><b>${stateLabel(s)}</b></div><div class="uld-number">${cur}</div><div class="uld-min">Minimum ${min}</div><div class="uld-bar"><i style="width:${Math.min(100,Math.max(0,(cur/Math.max(min*2,1))*100))}%"></i></div></div>`}).join('')+'</div>'}
function historyTable(rows=hist){return`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Type</th><th>ULD</th><th>Qty</th><th>Reference / Remarks</th><th>Flight</th><th>User</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.created_at)}</td><td><span class="movement ${movementType(x)==='IN'?'in':'out'}">${esc(movementType(x))}</span></td><td><b>${esc(uldType(x))}</b></td><td>${movementType(x)==='IN'?'+':'-'}${qty(x)}</td><td>${esc(x.reference)} ${esc(x.remarks)}</td><td>${esc(flight(x))}</td><td>${esc(userName(x))}</td></tr>`).join('')}</tbody></table></div>`}
async function show(page){const c=document.getElementById('content');c.innerHTML='<div class="box"><b>Loading...</b></div>';try{if(['dash','move','inv','hist','report'].includes(page))await load()}catch(e){c.innerHTML='<div class="box error"><b>Could not load data</b><p>'+esc(e.message)+'</p></div>';return}
if(page==='dash')c.innerHTML=`<h2>Current Stock Overview</h2>${lowAlert()}${stockCards()}<div class="two"><div class="box"><h3>Recent Activity</h3>${historyTable(hist.slice(0,8))}</div><div class="box"><h3>Stock Status</h3>${stock.map(x=>`<p class="status-line ${stockState(x)}"><b>${esc(uldType(x))}</b> — ${Number(x.current_stock)} / minimum ${Number(x.minimum_level)}</p>`).join('')}</div></div>`;
if(page==='move'){c.innerHTML=`<h2>In / Out — Stock Movement</h2><div class="box"><form id="mf"><select name="movement_type"><option>IN</option><option>OUT</option></select><select name="uld_type">${ULD_TYPES.map(x=>'<option>'+x+'</option>').join('')}</select><input name="quantity" type="number" min="1" placeholder="Quantity" required><input name="reference" placeholder="Reference / Remarks"><select name="flight_number"><option value="">Flight Number</option>${flights.map(x=>`<option value="${esc(x.flight_number)}">${esc(x.flight_number)}</option>`).join('')}</select><input name="remarks" placeholder="Additional remarks"><button>Submit Movement</button></form><p id="mm"></p></div>`;document.getElementById('mf').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.quantity=+d.quantity;try{await A('movement',d);show('dash')}catch(x){document.getElementById('mm').textContent=x.message}}}
if(page==='inv')c.innerHTML=`<h2>Inventory</h2>${lowAlert()}<div class="box"><div class="table-wrap"><table><tr><th>ULD</th><th>Current</th><th>Minimum</th><th>Status</th></tr>${stock.map(x=>`<tr><td><b>${esc(uldType(x))}</b></td><td>${x.current_stock}</td><td>${x.minimum_level}</td><td>${stateLabel(stockState(x))}</td></tr>`).join('')}</table></div></div>`;
if(page==='hist')c.innerHTML=`<h2>History</h2><div class="box">${historyTable()}</div>`;
if(page==='report')c.innerHTML=`<h2>Stock Summary</h2><div class="box print-area"><div class="print-header">${LOGO?`<img src="${esc(LOGO)}" alt="Logo">`:''}<div><h2>${esc(COMPANY)}</h2><p>MADAPT ULDs — Stock Summary</p><small>Generated: ${esc(new Date().toLocaleString())}</small></div></div><table><tr><th>ULD</th><th>Current</th><th>Minimum</th><th>Status</th></tr>${stock.map(x=>`<tr><td>${esc(uldType(x))}</td><td>${x.current_stock}</td><td>${x.minimum_level}</td><td>${stateLabel(stockState(x))}</td></tr>`).join('')}</table><button class="print-button" onclick="window.print()">Print Stock Summary</button></div>`;
if(page==='users')await users(c);if(page==='portals')await portals(c);if(page==='set')await settingsPage(c);if(page==='profile')await profilePage(c)}
async function profilePage(c){const photo=CURRENT_USER.profile_photo||'';c.innerHTML=`<h2>My Profile</h2><div class="box profile-box"><div class="media-preview"><div>${photo?`<img class="profile-photo" src="${esc(photo)}" alt="Profile photo">`:'<div class="profile-photo" style="display:flex;align-items:center;justify-content:center">◉</div>'}</div><div><h3>${esc(CURRENT_USER.full_name||CURRENT_USER.username)}</h3><p>${esc(CURRENT_USER.email||'')} · ${esc(CURRENT_USER.role||'')}</p></div></div><hr><h3>Profile photo</h3><p class="muted">Every approved user can upload or replace their own photo.</p><form id="pfoto" enctype="multipart/form-data"><div class="upload-row"><input name="profile_photo" type="file" accept="image/jpeg,image/png,image/webp" required><button>Upload Photo</button></div></form><p id="pmsg"></p></div>`;document.getElementById('pfoto').onsubmit=async e=>{e.preventDefault();try{const r=await A('profile_upload',new FormData(e.target),true);CURRENT_USER.profile_photo=r.profile_photo;document.getElementById('pmsg').textContent='Profile photo updated.';show('profile')}catch(x){document.getElementById('pmsg').textContent=x.message}}}
async function settingsPage(c){try{const r=await A('settings_get'),s=r.settings||{};flights=r.flights||[];recipients=r.recipients||[];c.innerHTML=`<h2>Settings</h2><div class="box"><h3>Company & Appearance</h3><form id="sf"><input name="company_name" value="${esc(s.company_name||'MADAPT ULDs')}" placeholder="Company name"><input name="primary" type="color" value="${esc(s.primary||'#087a46')}"><input name="accent" type="color" value="${esc(s.accent||'#1b8b5b')}"><input name="sidebar" type="color" value="${esc(s.sidebar||'#006b3c')}"><input type="hidden" name="logo_path" value="${esc(s.logo_path||'')}"><input type="hidden" name="aircraft_path" value="${esc(s.aircraft_path||'')}"><button>Save Settings</button></form><p id="sm"></p><div class="media-preview">${s.logo_path?`<img src="${esc(s.logo_path)}" alt="Logo">`:''}${s.aircraft_path?`<img src="${esc(s.aircraft_path)}" alt="Aircraft">`:''}</div><hr><h3>Upload Logo</h3><form id="logoForm" enctype="multipart/form-data"><div class="upload-row"><input name="logo" type="file" accept="image/jpeg,image/png,image/webp" required><button>Upload Logo</button></div></form><p id="lm"></p><h3>Upload Aircraft Image</h3><form id="airForm" enctype="multipart/form-data"><div class="upload-row"><input name="aircraft" type="file" accept="image/jpeg,image/png,image/webp" required><button>Upload Aircraft</button></div></form><p id="am"></p></div><div class="box"><h3>Low Stock Email Alert</h3><label class="check"><input id="lsa" type="checkbox" ${s.low_stock_alerts==='1'||s.low_stock_alerts==='true'?'checked':''}> Enable Low Stock Alerts</label><input id="les" value="${esc(s.low_stock_email_subject||'MADAPT ULDs - Low Stock Alert')}" placeholder="Email subject"><textarea id="lem" rows="10">${esc(s.low_stock_email_message||'Dear Team,\n\nThis is an automatic notification from MADAPT ULDs Inventory Management.\n\nULD {ULD_TYPE} has reached or fallen below its minimum stock level.\n\nCurrent stock: {CURRENT_STOCK}\nMinimum level: {MINIMUM_LEVEL}\n\nKind regards,\nMADAPT ULDs Inventory Management')}</textarea><button id="saveMail">Save Email Alert</button></div><div class="box"><h3>Alert Recipients</h3><form id="ef"><div class="upload-row"><input name="email" type="email" placeholder="email@example.com" required><button>Add Recipient</button></div></form><div>${recipients.map(x=>`<p><b>${esc(x.email)}</b> — ${Number(x.active)?'Active':'Disabled'} <button onclick="toggleEmail(${x.id})">Toggle</button> <button class="danger-btn" onclick="deleteEmail(${x.id})">Delete</button></p>`).join('')}</div></div><div class="box"><h3>Flights</h3><form id="ff"><div class="upload-row"><input name="flight_number" placeholder="ET740" required><button>Add Flight</button></div></form><div>${flights.map(x=>`<p><b>${esc(x.flight_number)}</b> — ${Number(x.active)?'Active':'Disabled'} <button onclick="toggleFlight(${x.id})">Toggle</button> <button class="danger-btn" onclick="deleteFlight(${x.id})">Delete</button></p>`).join('')}</div></div>`;
document.getElementById('sf').onsubmit=async e=>{e.preventDefault();try{await A('settings_save',Object.fromEntries(new FormData(e.target)));document.getElementById('sm').textContent='Saved successfully.'}catch(x){document.getElementById('sm').textContent=x.message}};document.getElementById('logoForm').onsubmit=async e=>{e.preventDefault();try{const r=await A('asset_upload',Object.assign(new FormData(e.target),{}),true)}catch(x){document.getElementById('lm').textContent=x.message;return}document.getElementById('lm').textContent='Logo uploaded. Reloading…';location.reload()};document.getElementById('airForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('kind','aircraft');try{await A('asset_upload',fd,true);document.getElementById('am').textContent='Aircraft image uploaded.';show('set')}catch(x){document.getElementById('am').textContent=x.message}};document.getElementById('logoForm').addEventListener('formdata',e=>e.formData.append('kind','logo'));document.getElementById('saveMail').onclick=async e=>{e.preventDefault();try{await A('settings_email_save',{enabled:document.getElementById('lsa').checked,subject:document.getElementById('les').value,message:document.getElementById('lem').value});alert('Low Stock email settings saved.')}catch(x){alert(x.message)}};document.getElementById('ef').onsubmit=async e=>{e.preventDefault();try{await A('alert_email_add',Object.fromEntries(new FormData(e.target)));show('set')}catch(x){alert(x.message)}};document.getElementById('ff').onsubmit=async e=>{e.preventDefault();try{await A('flight_add',Object.fromEntries(new FormData(e.target)));show('set')}catch(x){alert(x.message)}}}catch(e){c.innerHTML='<div class="box error">'+esc(e.message)+'</div>'}}
async function users(c){try{const r=await A('users');c.innerHTML=`<h2>User Approval</h2><div class="box"><div class="table-wrap"><table><tr><th>User</th><th>Name</th><th>Photo</th><th>Role</th><th>Status</th><th>Action</th></tr>${r.users.map(x=>`<tr><td>${esc(x.username)}</td><td>${esc(x.full_name)}</td><td>${x.profile_photo?`<img src="${esc(x.profile_photo)}" style="width:36px;height:36px;border-radius:50%;object-fit:cover">`:''}</td><td><select onchange="setRole(${x.id},this.value)"><option ${x.role==='OPERATOR'?'selected':''}>OPERATOR</option><option ${x.role==='SUPERVISOR'?'selected':''}>SUPERVISOR</option><option ${x.role==='ADMIN'?'selected':''}>ADMIN</option></select></td><td>${Number(x.active)?'approved':'pending'}</td><td>${Number(x.active)?'':'<button onclick="ap('+x.id+',\'approved\')">Approve</button>'}</td></tr>`).join('')}</table></div></div>`}catch(e){c.innerHTML='<div class="box error">'+esc(e.message)+'</div>'}}
async function portals(c){try{const r=await A('portals');portalList=r.portals||[];c.innerHTML=`<h2>Portals</h2><p class="muted">Access operational portals from one place. Only administrators can add, edit or delete portals.</p>${IS_ADMIN?'<div class="box"><h3>Portal Administration</h3><form id="portalForm"><input name="name" placeholder="Portal name" required><input name="url" placeholder="https://..." required><input name="description" placeholder="Description"><input name="logo_path" placeholder="Logo path"><button>Add Portal</button></form><p id="portalMsg"></p></div>':''}<div class="portal-grid">${portalList.map(x=>`<div class="portal-card"><div class="portal-logo">${x.logo_path?`<img src="${esc(x.logo_path)}" alt="">`:'🌐'}</div><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><a href="${esc(x.url)}" target="_blank" rel="noopener">Open Portal ↗</a>${IS_ADMIN?`<div class="portal-actions"><button onclick="editPortal(${x.id})">Edit</button> <button class="danger-btn" onclick="deletePortal(${x.id})">Delete</button></div>`:''}</div>`).join('')}</div>`;if(IS_ADMIN)document.getElementById('portalForm').onsubmit=async e=>{e.preventDefault();try{await A('portal_add',Object.fromEntries(new FormData(e.target)));show('portals')}catch(x){document.getElementById('portalMsg').textContent=x.message}}}catch(e){c.innerHTML='<div class="box error">'+esc(e.message)+'</div>'}}
async function editPortal(id){if(!IS_ADMIN)return;const x=portalList.find(p=>+p.id===+id);if(!x)return;const name=prompt('Portal name',x.name);if(name===null)return;const url=prompt('Portal URL',x.url);if(url===null)return;const description=prompt('Description',x.description||'');if(description===null)return;const logo_path=prompt('Logo path',x.logo_path||'');if(logo_path===null)return;try{await A('portal_update',{id,name:name.trim(),url:url.trim(),description:description.trim(),logo_path:logo_path.trim()});show('portals')}catch(e){alert(e.message)}}
async function deletePortal(id){if(!IS_ADMIN)return;if(!confirm('Delete this portal?'))return;try{await A('portal_delete',{id});show('portals')}catch(e){alert(e.message)}}
async function ap(id,status){try{await A('approve',{id,status});show('users')}catch(e){alert(e.message)}}async function setRole(id,role){try{await A('set_role',{id,role})}catch(e){alert(e.message)}}async function deleteEmail(id){if(confirm('Delete recipient?'))try{await A('alert_email_delete',{id});show('set')}catch(e){alert(e.message)}}async function toggleEmail(id){try{await A('alert_email_toggle',{id});show('set')}catch(e){alert(e.message)}}async function deleteFlight(id){if(confirm('Delete flight?'))try{await A('flight_delete',{id});show('set')}catch(e){alert(e.message)}}async function toggleFlight(id){try{await A('flight_toggle',{id});show('set')}catch(e){alert(e.message)}}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>show(b.dataset.page));document.getElementById('logoutBtn').onclick=async()=>{try{await A('logout')}finally{location.href='login.php'}};show('dash');
</script></body></html>